import 'package:flutter/material.dart';import 'package:flutter_bloc/flutter_bloc.dart';import 'package:flutter_svg/flutter_svg.dart';import 'package:go_router/go_router.dart';import 'package:sizer/sizer.dart';import 'package:smart_coach_new/core/utils/color_constants.dart';import 'package:smart_coach_new/core/utils/image_utils.dart';import 'package:smart_coach_new/core/utils/loader.dart';import 'package:smart_coach_new/core/utils/toast_message_utils.dart';import 'package:smart_coach_new/core/utils/utils.dart';import 'package:smart_coach_new/core/widgets/custom_button.dart';import 'package:smart_coach_new/core/widgets/custom_text_field.dart';import 'package:smart_coach_new/features/auth/login/presentation/bloc/login_bloc.dart';import 'package:smart_coach_new/features/auth/login/presentation/bloc/login_event.dart';import 'package:smart_coach_new/features/auth/login/presentation/bloc/login_state.dart';import 'package:smart_coach_new/routes/app_router.dart';class LoginScreen extends StatefulWidget {  const LoginScreen({super.key});  @override  State<LoginScreen> createState() => _LoginScreenState();}class _LoginScreenState extends State<LoginScreen> {  final TextEditingController emailOrNumberController = TextEditingController();  final TextEditingController passwordController = TextEditingController();  // int indexOfSelectedLoginMethod = 0;  late LoginBloc _loginBloc;  @override  void initState() {    super.initState();    _loginBloc = context.read<LoginBloc>();  }  @override  Widget build(BuildContext context) {    return BlocListener<LoginBloc, LoginState>(      listener: (context, state) {        if (state is LoginLoading) {          Loader.show();        } else {          Loader.dismiss();        }        if (state is LoginSuccess) {          ToastMessageUtils.showMessage(context, state.message);          context.go(AppRouter.dashboardRoute);        }        if (state is LoginFailure) {          Utils.showApiErrorMessageOrList(context, message: state.message, errorList: state.errorList);        }      },      child: Scaffold(        body: SafeArea(          child: Container(            margin: EdgeInsets.symmetric(horizontal: 5.w, vertical: 6.h),            decoration: BoxDecoration(              color: Colors.white,              borderRadius: BorderRadius.circular(6.w),              boxShadow: [                BoxShadow(                  color: Colors.black.withValues(alpha: 0.05),                  blurRadius: 12,                  offset: Offset(2, 8),                ),              ],            ),            child: Center(              child: Container(                padding: EdgeInsets.symmetric(horizontal: 5.w),                child: SingleChildScrollView(                  child: Column(                    mainAxisAlignment: MainAxisAlignment.center,                    mainAxisSize: MainAxisSize.min,                    children: [                      Container(                        height: 9.5.h,                        width: 9.5.h,                        decoration: BoxDecoration(                          image: DecorationImage(                            image: AssetImage(                              ImageUtils.pisolve,                            ),                            fit: BoxFit.cover,                          ),                        ),                      ),                      SizedBox(height: 2.h),                      SizedBox(                        height: 5.h,                        width: 5.h,                        child: SvgPicture.asset(                          ImageUtils.icTrain,                          fit: BoxFit.contain,                        ),                      ),                      Text(                        "Smart Coach",                        style: TextStyle(                          fontSize: 14.sp,                          fontWeight: FontWeight.w600,                          color: ColorConstants.subTextLightBlueColor,                        ),                      ),                      SizedBox(height: 1.h),                      Text(                        "Sign in to your account",                        style: TextStyle(                          fontSize: 17.sp,                          fontWeight: FontWeight.w800,                        ),                      ),                      SizedBox(height: 0.3.h),                      Text(                        "Verify your identity to continue.",                        style: TextStyle(                          fontSize: 12.sp,                          color: Colors.black,                        ),                      ),                      SizedBox(height: 3.h),                      BlocBuilder<LoginBloc, LoginState>(                          builder: (context, state) {                            return Column(                              mainAxisAlignment: MainAxisAlignment.center,                              mainAxisSize: MainAxisSize.min,                              children: [                                Container(                                  padding: EdgeInsets.all(1),                                  decoration: BoxDecoration(                                    color: Colors.grey[200],                                    borderRadius: BorderRadius.circular(25),                                  ),                                  child: Row(                                    children: [                                      Expanded(                                        child: _buttonChipView(0, 'Email',                                            _loginBloc.isLoginWithEmail),                                      ),                                      Expanded(                                        child: _buttonChipView(1, 'Phone Number',                                            !_loginBloc.isLoginWithEmail),                                      ),                                    ],                                  ),                                ),                                SizedBox(height: 2.5.h),                                _loginBloc.isLoginWithEmail                                    ? _emailField()                                    : _phoneNumberField(),                              ],                            );                          }),                      SizedBox(height: 1.5.h),                      CustomTextField(                        hintText: 'Enter your password',                        labelText: 'Password',                        prefixIcon: Icons.lock_outline,                        isPassword: true,                        controller: passwordController,                      ),                      SizedBox(height: 3.h),                      CustomButton(                        text: 'Login',                        // onPressed: (){                        //   context.go(AppRouter.dashboardRoute);                        // },                        onPressed: () {                          String emailOrNumber =                          emailOrNumberController.text.trim();                          String password = passwordController.text.trim();                          if (_isValid(emailOrNumber, password)) {                            _loginBloc.add(LoginRequested(                                emailOrNumberController.text.trim(),                                passwordController.text.trim()));                          }                        },                      ),                      // SizedBox(height: 2.h),                      // Row(                      //   mainAxisAlignment: MainAxisAlignment.center,                      //   children: [                      //     GestureDetector(                      //       onTap: () {                      //         context.push(AppRouter.registerRoute);                      //       },                      //       child: Text(                      //         'Login with OTP',                      //         style: TextStyle(                      //           fontSize: 11.sp,                      //           fontWeight: FontWeight.w500,                      //           color: ColorConstants.subTextLightBlueColor,                      //         ),                      //       ),                      //     ),                      //     Text(                      //       " | ",                      //       style: TextStyle(                      //         color: ColorConstants.subTextLightBlueColor,                      //         fontSize: 11.sp,                      //       ),                      //     ),                      //     GestureDetector(                      //       onTap: () {                      //         context.push(AppRouter.registerRoute);                      //       },                      //       child: Text(                      //         'Register User',                      //         style: TextStyle(                      //           fontSize: 11.sp,                      //           fontWeight: FontWeight.w500,                      //           color: ColorConstants.subTextLightBlueColor,                      //         ),                      //       ),                      //     ),                      //   ],                      // ),                    ],                  ),                ),              ),            ),          ),        ),      ),    );  }  Widget _buttonChipView(int index, String name, bool isSelected) {    return GestureDetector(      onTap: () {        _loginBloc            .add(LoginWithEmailOrNumberToggled(!_loginBloc.isLoginWithEmail));      },      child: Container(        decoration: BoxDecoration(          color: isSelected ? Colors.blue : Color(0xFFF1F1F3),          borderRadius: BorderRadius.circular(25),        ),        padding: EdgeInsets.symmetric(          vertical: 1.25.h,        ),        child: Center(          child: Text(            name,            style: TextStyle(              color: isSelected ? Colors.white : Colors.black54,              fontSize: 10.5.sp,              fontWeight: FontWeight.w500,            ),          ),        ),      ),    );  }  Widget _emailField() {    return CustomTextField(      hintText: 'Enter your email',      labelText: 'Email address',      prefixIcon: Icons.email_outlined,      textInputAction: TextInputAction.next,      controller: emailOrNumberController,      textInputType: TextInputType.emailAddress,      key: ValueKey('Email'),    );  }  Widget _phoneNumberField() {    return CustomTextField(      hintText: 'Enter your phone number',      labelText: 'Phone number',      prefixIcon: Icons.call_outlined,      textInputAction: TextInputAction.next,      controller: emailOrNumberController,      textInputType: TextInputType.number,      key: ValueKey('Number'),    );  }  bool _isValid(String emailOrNumber, String password) {    if (emailOrNumber.isEmpty) {      ToastMessageUtils.showMessage(context,          'Please enter valid ${_loginBloc.isLoginWithEmail ? 'email address' : 'phone number'}');      return false;    } else if (password.isEmpty) {      ToastMessageUtils.showMessage(context, 'Please enter valid password');      return false;    } else {      return true;    }  }}